const http=require('node:http');
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const get=url=>new Promise((resolve,reject)=>{http.get(url,r=>{let text='';r.on('data',b=>text+=b);r.on('end',()=>{try{resolve(JSON.parse(text))}catch(e){reject(e)}})}).on('error',reject)});
class Cdp{
 constructor(socket){this.socket=socket;this.sequence=0;this.pending=new Map();this.contexts=new Map();socket.addEventListener('message',event=>{const m=JSON.parse(event.data);if(m.id){const req=this.pending.get(m.id);if(req){clearTimeout(req.timer);this.pending.delete(m.id);if(m.error)req.reject(Error(JSON.stringify(m.error)));else req.resolve(m.result)}}else if(m.method==='Runtime.executionContextCreated'){const context=m.params.context;this.contexts.set(m.sessionId+':'+context.id,{session:m.sessionId,id:context.id,name:context.name,origin:context.origin})}else if(m.method==='Runtime.executionContextsCleared')for(const [k,v]of this.contexts)if(v.session===m.sessionId)this.contexts.delete(k)});}
 static async connect(port){let data;for(let i=0;i<200;i++){try{data=await get(`http://127.0.0.1:${port}/json/version`);break}catch{await sleep(100)}}if(!data)throw Error('CDP unavailable');const socket=new WebSocket(data.webSocketDebuggerUrl);await new Promise((resolve,reject)=>{socket.addEventListener('open',resolve,{once:true});socket.addEventListener('error',reject,{once:true})});return new Cdp(socket)}
 send(method,params={},sessionId){const id=++this.sequence;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{this.pending.delete(id);reject(Error('CDP timeout '+method))},10000);this.pending.set(id,{resolve,reject,timer});this.socket.send(JSON.stringify({id,method,params,...(sessionId?{sessionId}:{})}))})}
 async attach(){const {targetInfos}=await this.send('Target.getTargets');for(const target of targetInfos.filter(t=>['page','iframe','webview'].includes(t.type))){if(this.targets?.has(target.targetId))continue;this.targets??=new Map();const {sessionId}=await this.send('Target.attachToTarget',{targetId:target.targetId,flatten:true});this.targets.set(target.targetId,sessionId);await this.send('Runtime.enable',{},sessionId)}return targetInfos}
 async eval(expression,context){const r=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,...(context?{contextId:context.id}:{})},context?.session);if(r.exceptionDetails)throw Error(r.exceptionDetails.text+': '+r.exceptionDetails.exception?.description);return r.result.value}
 async find(selector){for(let n=0;n<200;n++){await this.attach();for(const context of [...this.contexts.values()].sort((a,b)=>Number(!!a.name)-Number(!!b.name))){try{if(await this.eval(`!!document.querySelector(${JSON.stringify(selector)})`,context))return context}catch{ /* A navigating context will be rediscovered. */ }}await sleep(100)}throw Error('UI context not found '+selector+' '+JSON.stringify([...this.contexts.values()]))}
 async key(context,key,code=key,modifiers=0){const windowsVirtualKeyCode=({Backspace:8,Tab:9,Enter:13,Escape:27,Home:36,ArrowLeft:37,ArrowUp:38,ArrowRight:39,ArrowDown:40})[key]||0;await this.send('Input.dispatchKeyEvent',{type:windowsVirtualKeyCode?'rawKeyDown':'keyDown',key,code,modifiers,windowsVirtualKeyCode,...(key.length===1&&!modifiers?{text:key}:{})},context.session);await this.send('Input.dispatchKeyEvent',{type:'keyUp',key,code,modifiers,windowsVirtualKeyCode},context.session)}
 async click(context,selector){if(!context.origin.startsWith('vscode-file:'))await this.eval(`document.querySelector(${JSON.stringify(selector)}).scrollIntoView({block:'center'})`,context);await sleep(100);let box;if(context.origin.startsWith('vscode-file:')){box=await this.eval(`(()=>{const b=document.querySelector(${JSON.stringify(selector)}).getBoundingClientRect();return{x:b.x+b.width/2,y:b.y+b.height/2}})()`,context)}else{const handle=await this.send('Runtime.evaluate',{expression:`document.querySelector(${JSON.stringify(selector)})`,contextId:context.id},context.session);const {model}=await this.send('DOM.getBoxModel',{objectId:handle.result.objectId},context.session);const quad=model.border;box={x:(quad[0]+quad[2]+quad[4]+quad[6])/4,y:(quad[1]+quad[3]+quad[5]+quad[7])/4};await this.send('Runtime.releaseObject',{objectId:handle.result.objectId},context.session)}await this.send('Input.dispatchMouseEvent',{type:'mouseMoved',...box},context.session);await sleep(30);await this.send('Input.dispatchMouseEvent',{type:'mousePressed',...box,button:'left',clickCount:1},context.session);await this.send('Input.dispatchMouseEvent',{type:'mouseReleased',...box,button:'left',clickCount:1},context.session)}
 close(){for(const req of this.pending.values()){clearTimeout(req.timer);req.reject(Error('CDP closed'))}this.pending.clear();this.socket.close()}
}
module.exports={Cdp,sleep};
